formulas.expression:
IF(
    OR(
        AND(
            TEXT({!$Record.pse__Resource__r.pse__Work_Calendar__r.pse__Week_Start_Day__c}) = 'Monday',
            WEEKDAY({!$Record.pse__End_Date__c}) = 7,
            DAY({!$Record.pse__End_Date__c}) - 1 = {!For_HolidayHrsFirstWk}
        ),
	AND(
            TEXT({!$Record.pse__Resource__r.pse__Work_Calendar__r.pse__Week_Start_Day__c}) = 'Sunday',
            WEEKDAY({!$Record.pse__End_Date__c}) = 6,
            DAY({!$Record.pse__End_Date__c}) - 1 = {!For_HolidayHrsFirstWk}
        ),
     AND(
            TEXT({!$Record.pse__Resource__r.pse__Work_Calendar__r.pse__Week_Start_Day__c}) = 'Monday',
            WEEKDAY({!$Record.pse__End_Date__c}) = 1,
            DAY({!$Record.pse__End_Date__c}) - 2 = {!For_HolidayHrsFirstWk}
        ),        
        AND(
            TEXT({!$Record.pse__Resource__r.pse__Work_Calendar__r.pse__Week_Start_Day__c}) = 'Sunday',
            WEEKDAY({!$Record.pse__End_Date__c}) = 7,
            DAY({!$Record.pse__End_Date__c}) - 2 = {!For_HolidayHrsFirstWk}
        )),
   0,1)

IF(
    OR(
        AND(
            TEXT({!$Record.pse__Resource__r.pse__Work_Calendar__r.pse__Week_Start_Day__c}) = 'Monday',
            WEEKDAY({!$Record.pse__End_Date__c}) = 7,
            DAY({!$Record.pse__End_Date__c}) - 1 > {!For_HolidayHrsFirstWk}
        ),
	AND(
            TEXT({!$Record.pse__Resource__r.pse__Work_Calendar__r.pse__Week_Start_Day__c}) = 'Sunday',
            WEEKDAY({!$Record.pse__End_Date__c}) = 6,
            DAY({!$Record.pse__End_Date__c}) - 1 > {!For_HolidayHrsFirstWk}
        )),
    (DAY({!$Record.pse__End_Date__c}) - {!For_HolidayHrsFirstWk} - 1) *
        ({!$Record.pse__Resource__r.pse__Work_Calendar__r.pse__Monday_Hours__c} * {!Var_MinHrs_Custom}) / 100,
        IF(
     OR(
        AND(
            TEXT({!$Record.pse__Resource__r.pse__Work_Calendar__r.pse__Week_Start_Day__c}) = 'Monday',
            WEEKDAY({!$Record.pse__End_Date__c}) = 1,
            DAY({!$Record.pse__End_Date__c}) - 2 > {!For_HolidayHrsFirstWk}
        ),        
        AND(
            TEXT({!$Record.pse__Resource__r.pse__Work_Calendar__r.pse__Week_Start_Day__c}) = 'Sunday',
            WEEKDAY({!$Record.pse__End_Date__c}) = 7,
            DAY({!$Record.pse__End_Date__c}) - 2 > {!For_HolidayHrsFirstWk}
        )),
    (DAY({!$Record.pse__End_Date__c}) - {!For_HolidayHrsFirstWk} - 2) *
        ({!$Record.pse__Resource__r.pse__Work_Calendar__r.pse__Monday_Hours__c} * {!Var_MinHrs_Custom}) / 100,(DAY({!$Record.pse__End_Date__c}) - {!For_HolidayHrsFirstWk}) *
        ({!$Record.pse__Resource__r.pse__Work_Calendar__r.pse__Monday_Hours__c} * {!Var_MinHrs_Custom}) / 100
    ))

IF(
    OR(
        AND(
            TEXT({!$Record.pse__Resource__r.pse__Work_Calendar__r.pse__Week_Start_Day__c}) = 'Monday',
            WEEKDAY({!For_LastDate}) = 7,
            DAY({!For_LastDate}) - 1 > {!For_HolidayHrsLastWk}
        ),
	AND(
            TEXT({!$Record.pse__Resource__r.pse__Work_Calendar__r.pse__Week_Start_Day__c}) = 'Sunday',
            WEEKDAY({!For_LastDate}) = 6,
            DAY({!For_LastDate}) - 1 > {!For_HolidayHrsLastWk}
        )),
DAY({!For_LastDate})-DAY({!$Record.pse__Start_Date__c}),
IF(
          OR(
               AND(
            TEXT({!$Record.pse__Resource__r.pse__Work_Calendar__r.pse__Week_Start_Day__c}) = 'Monday',
            WEEKDAY({!For_LastDate}) = 1,
            DAY({!For_LastDate}) - 2 > {!For_HolidayHrsLastWk}
        ),        
              AND(
            TEXT({!$Record.pse__Resource__r.pse__Work_Calendar__r.pse__Week_Start_Day__c}) = 'Sunday',
            WEEKDAY({!For_LastDate}) = 7,
            DAY({!For_LastDate}) - 2 > {!For_HolidayHrsLastWk}
        )),
DAY({!For_LastDate})-DAY({!$Record.pse__Start_Date__c})-1,DAY({!For_LastDate})-DAY({!$Record.pse__Start_Date__c})+1
    ))
